import java.util.*;

class TriangleArea
{
    static double area(double base, double height)
    {
        return 0.5 * base * height;
    }

    static double area(double a, double b, double c)
    {
        double s = (a + b + c) / 2.0;       // semi-perimeter
        return Math.sqrt(s * (s - a) * (s - b) * (s - c));
    }

    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter base and height: ");
        double bs = sc.nextDouble();
        double h = sc.nextDouble();
        System.out.println("Area (base and height) = " + area(bs, h));
        System.out.print("Enter the three sides: ");
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        double z = sc.nextDouble();
        System.out.println("Area (Heron's formula) = " + area(x, y, z));
    }
}
Sample: base 6, height 4 gives 12.0; sides 3, 4, 5 give s = 6 and area = sqrt(6*3*2*1) = 6.0
(In area2, s is the semi-perimeter (a + b + c) / 2.)

