import java.util.*;

class ParkingLot
{
    int vno;
    int hours;
    double bill;

    void input()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter vehicle number: ");
        vno = sc.nextInt();
        System.out.print("Enter number of hours: ");
        hours = sc.nextInt();
    }

    void calculate()
    {
        if (hours <= 1)
            bill = 3.0;
        else
            bill = 3.0 + (hours - 1) * 1.50;
    }

    void display()
    {
        System.out.println("Vehicle number : " + vno);
        System.out.println("Hours parked   : " + hours);
        System.out.println("Bill (Rs)      : " + bill);
    }

    public static void main(String args[])
    {
        ParkingLot ob = new ParkingLot();
        ob.input();
        ob.calculate();
        ob.display();
    }
}
Sample: 5 hours gives 3 + 4 x 1.50 = Rs 7.5
(The first hour or part of it is charged Rs 3, so hours <= 1 gives a bill of 3.0. The source program wrote bill = 3 * hours, which would charge 0 for 0 hours.)

